    n.pos.x += n.vel.x;
    n.pos.y += n.vel.y;
    
    if(n.pos.x < 0 || n.pos.x > width) n.vel.x *= -1;
    if(n.pos.y < 0 || n.pos.y > height) n.vel.y *= -1;
    
